function validateExtensionData(b) {
  validatePlannerData(b);
  if (!b || typeof b !== 'object') return;
  const p=b.profile;
  if (p && typeof p==='object') {
    for(const key of ['birthDate','club','discipline','strengthExperience','workSchedule','limitations','excludedExercises','trainingPreferences','weightCategory'])
      if(p[key]!==undefined&&(typeof p[key]!=='string'||p[key].length>2000))throw Error('Neplatné údaje profilu.');
    if(p.birthDate && (!/^\d{4}-\d{2}-\d{2}$/.test(p.birthDate)||!validDate(p.birthDate)||p.birthDate>today()))throw Error('Neplatné datum narození.');
    for(const [key,min,max] of [['heightCm',100,250],['bjjYears',0,80],['sessionMinutes',10,300]])
      if(p[key]!==undefined&&(typeof p[key]!=='number'||!Number.isFinite(p[key])||p[key]<min||p[key]>max))throw Error('Neplatná číselná hodnota profilu.');
    for(const key of ['priorities','availableEquipment'])if(p[key]!==undefined&&(!Array.isArray(p[key])||p[key].length>40||p[key].some(x=>typeof x!=='string'||x.length>100)))throw Error('Neplatné možnosti profilu.');
  }
  if(b.customExercises!==undefined) {
    if(!Array.isArray(b.customExercises)||b.customExercises.length>2000)throw Error('Neplatný vlastní zásobník cviků.');
    const ids=new Set(),names=new Set();
    for(const e of b.customExercises) {
      if(!e||typeof e.id!=='string'||!e.id.startsWith('custom-')||e.id.length>250||ids.has(e.id)||typeof e.name!=='string'||!e.name.trim()||e.name.length>100)throw Error('Neplatný nebo duplicitní vlastní cvik.');
      const name=e.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
      if(names.has(name))throw Error('Duplicitní název vlastního cviku.');
      if(!EXERCISE_CATEGORIES.some(c=>c.id===e.category)||!Object.hasOwn(EXERCISE_EQUIPMENT,e.equipment)||!['reps','seconds','meters'].includes(e.unit))throw Error('Neplatná partie, vybavení nebo jednotka cviku.');
      if(!Array.isArray(e.aliases)||e.aliases.length>30||e.aliases.some(x=>typeof x!=='string'||x.length>150)||(e.notes!==undefined&&(typeof e.notes!=='string'||e.notes.length>2000)))throw Error('Neplatné poznámky cviku.');
      ids.add(e.id);names.add(name);
    }
  }
  if(b.exerciseFavorites!==undefined&&(!Array.isArray(b.exerciseFavorites)||b.exerciseFavorites.length>5000||b.exerciseFavorites.some(x=>typeof x!=='string'||x.length>250)))throw Error('Neplatné oblíbené cviky.');
  for(const e of b.sessions||[])for(const x of e.sets||[]) {
    if(x.done!==undefined&&typeof x.done!=='boolean')throw Error('Neplatný stav série.');
    if(x.perSide!==undefined&&typeof x.perSide!=='boolean')throw Error('Neplatné provedení na stranu.');
    if(x.loadMode!==undefined&&!['weight','assistance','bodyweight'].includes(x.loadMode))throw Error('Neplatný druh zátěže.');
    if(x.restSeconds!==undefined&&(typeof x.restSeconds!=='number'||!Number.isFinite(x.restSeconds)||x.restSeconds<0||x.restSeconds>3600))throw Error('Neplatná pauza mezi sériemi.');
    if(x.tempo!==undefined&&(typeof x.tempo!=='string'||x.tempo.length>30))throw Error('Neplatné tempo.');
  }
}
